        },
        {
          "kind": "metric",
          "sql": "SELECT date_trunc('minute', time) AS minute, metric, round(avg(value),3) AS avg_value FROM abnormal_metrics WHERE service_name='ts-verification-code-service' AND metric='jvm.cpu.recent_utilization' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "JVM CPU utilization stays near zero during the container CPU burst, so the burn is outside the JVM process."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS minute, service_name, count(*) AS n, sum(CASE WHEN attr_http_response_status_code=503 THEN 1 ELSE 0 END) AS http503, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE (service_name='ts-verification-code-service' AND attr_span_kind='Server') OR (service_name='ts-ui-dashboard' AND span_name LIKE '%verifycode%') GROUP BY 1,2 ORDER BY 1,2",
